const event = $input.first().json;
const execution = event.execution || {};
const executionReference = String(execution.id || '').trim();
if (!executionReference) {
  throw new Error('PTS error audit requires an execution reference');
}
const message = String(execution.error?.message || event.error?.message || '').toLowerCase();
let category = 'unknown';
if (/auth|credential|login|password/.test(message)) category = 'authentication';
else if (/timeout|timed out/.test(message)) category = 'source_timeout';
else if (/502|503|504|bad gateway|unavailable/.test(message)) category = 'source_unavailable';
else if (/account|studio target|configuration|mapping/.test(message)) category = 'configuration';
else if (/supabase|postgres|warehouse|upsert|rpc/.test(message)) category = 'warehouse';
else if (/invalid|validation|missing|required|duplicate|mismatch/.test(message)) category = 'validation';
return [{ json: {
  executionReference,
  category,
  body: {
    p_execution_reference: executionReference,
    p_status: 'failed',
    p_rows_processed: 0,
    p_error_category: category
  }
} }];
